// Aggregate the SHA-bound six-module Ghidra ORIGINAL static gap reports.
// Reports must first be generated by private original-byte audit commands.
// This tool ONLY ranks unresolved *static candidates*, never marks a game
// function, opcode, DOS trace, or browser behavior as verified.
export function rankOriginalUw2ModuleGaps(reports,manifest){
  if(!manifest||!Array.isArray(manifest.coreExecutables)||
     manifest.coreExecutables.length!==6)
    throw new Error('pinned six original Korean modules required');
  if(!Array.isArray(reports)||reports.length!==6)
    throw new Error('one independently audited static report per original module required');
  const expected=new Map();
  for(const row of manifest.coreExecutables){
    if(expected.has(row.name)||!row.sha256||
       !/^[a-f0-9]{64}$/.test(row.sha256))
      throw new Error('invalid or duplicate original Korean module fingerprint');
    expected.set(row.name,row);
  }
  const seen=new Set(),ranked=[];
  const safe=(n,label)=>{if(!Number.isSafeInteger(n)||n<0)
      throw new Error('invalid static count: '+label);return n;};
  for(const report of reports){
    if(!report||typeof report!=='object'||Array.isArray(report)||
       !expected.has(report.moduleName)||seen.has(report.moduleName))
      throw new Error('unknown or duplicate original module report');
    const pin=expected.get(report.moduleName);
    if(report.sha256!==pin.sha256||report.providerVersion!=='12.1.4')
      throw new Error('Ghidra report original SHA/version not pinned');
    if(report.verifiedCodeBytes!==0||report.verifiedFunctionCount!==0||
       report.gate!=='HOLD_UNRESOLVED_FLOW'&&
       report.gate!=='HOLD_STATIC_ONLY'&&report.gate!=='HOLD_UNVERIFIED_COM')
      throw new Error('unverified candidate cannot become verified gameplay');
    const moduleBytes=pin.mz?.imageBytes??pin.com?.fileBytes;
    const code=safe(report.codeCandidateBytes,'code candidate');
    const missing=safe(report.unobservedImageBytes??report.unobservedBytes,'unobserved');
    const instructionCandidates=safe(report.instructionCandidates,'instruction candidates');
    const functionCandidates=safe(report.functionEntryCandidates,'function candidates');
    const unresolved=safe(report.unresolvedStaticFlows,'unresolved flows');
    if(moduleBytes!==code+missing||code>moduleBytes||
       instructionCandidates>code||functionCandidates>moduleBytes)
      throw new Error('original static candidate byte conservation failed');
    if(pin.mz){
      if(safe(report.uniqueChunks,'windows')!==Math.ceil(moduleBytes/65536))
        throw new Error('MZ full-image chunk manifest missing');
    }else if(report.originalBytes!==moduleBytes||report.loadBase!==0x10100){
      throw new Error('COM PSP+0100h audited image mismatch');
    }
    seen.add(report.moduleName);
    ranked.push({moduleName:report.moduleName,originalSha256:pin.sha256,
      initializedBytes:moduleBytes,candidateCodeBytes:code,
      unobservedBytes:missing,unresolvedStaticFlows:unresolved,
      instructionCandidates,functionEntryCandidates:functionCandidates,
      verifiedCodeBytes:0,verifiedFunctionCount:0,
      gate:'HOLD_STATIC_ORIGINAL_DOS_UNTESTED'});
  }
  if(seen.size!==expected.size)
    throw new Error('six-module analysis incomplete');
  ranked.sort((a,b)=>b.unobservedBytes-a.unobservedBytes||
    b.unresolvedStaticFlows-a.unresolvedStaticFlows||
    a.moduleName.localeCompare(b.moduleName));
  const totals=ranked.reduce((x,m)=>({
    bytes:x.bytes+m.initializedBytes,
    codeCandidates:x.codeCandidates+m.candidateCodeBytes,
    unobserved:x.unobserved+m.unobservedBytes,
    unresolvedFlows:x.unresolvedFlows+m.unresolvedStaticFlows
  }),{bytes:0,codeCandidates:0,unobserved:0,unresolvedFlows:0});
  return {
    schemaVersion:1,modules:ranked,totals,
    verifiedCodeBytes:0,verifiedFunctionCount:0,
    gate:'HOLD_UNVERIFIED_STATIC_GHIDRA_ONLY',
    caveat:'Six full-file Ghidra candidate inventories, not verified x86 code, decompilation, DOS execution, original game functionality or browser fidelity'
  };
}
